PHYS='<script type="application/ld+json">\n{\n  "@context": "https://schema.org",\n  "@type": "Physician",\n  "name": "Dr. David Lazo Pérez",\n  "subjectOf": {\n    "@type": "ProfilePage",\n    "@id": "https://cirugiatoracica.cl/cv#page"\n  },\n  "honorificSuffix": "FACS",\n  "jobTitle": "Cirujano Torácico",\n  "medicalSpecialty": [\n    "Cirugía Torácica",\n    "Cirugía Robótica",\n    "Broncoscopía Intervencionista"\n  ],\n  "url": "https://rats.cl/",\n  "image": "https://rats.cl/imgs/foto-dr-lazo.jpg",\n  "worksFor": [\n    {\n      "@type": "Hospital",\n      "name": "Clínica Las Condes"\n    },\n    {\n      "@type": "Hospital",\n      "name": "Hospital Clínico San Borja Arriarán"\n    }\n  ],\n  "sameAs": [\n    "https://orcid.org/0009-0007-0806-6679",\n    "https://cirugiatoracica.cl",\n    "https://rats.cl",\n    "https://videotoracoscopia.cl",\n    "https://broncoscopia.cl",\n    "https://cancerpulmonar.cl",\n    "https://hiperhidrosis.cl",\n    "https://www.linkedin.com/in/david-lazo-p%C3%A9rez-7b194748/",\n    "https://www.instagram.com/dr.david.lazo.p/",\n    "https://www.doctoralia.cl/david-rene-lazo-perez-3/cirujano-toracico-cirujano-general/santiago",\n    "https://www.doctoralia.cl/david-rene-lazo-perez/cirujano-toracico-cirujano-general/las-condes",\n    "https://www.topdoctors.cl/doctor/david-rene-lazo-perez/",\n    "https://www.ctsnet.org/home/dlazo",\n    "https://encuadrado.com/p/david-lazo-perez/"\n  ],\n  "knowsAbout": [\n    "Cirugía Torácica",\n    "Cirugía Robótica RATS",\n    "EBUS",\n    "CryoEBUS",\n    "Cáncer Pulmonar",\n    "VATS",\n    "Trasplante Pulmonar",\n    "Hiperhidrosis",\n    "Cirugía Mínimamente Invasiva"\n  ],\n  "hasCredential": [\n    {\n      "@type": "EducationalOccupationalCredential",\n      "credentialCategory": "Especialidad médica",\n      "name": "Cirugía Torácica — Universidad de Chile"\n    }\n  ],\n  "areaServed": "Santiago, Chile",\n  "availableService": "Consulta presencial Clínica Las Condes y telemedicina",\n  "@id": "https://cirugiatoracica.cl/#david-lazo",\n  "memberOf": [\n    {\n      "@type": "MedicalOrganization",\n      "name": "World Association for Bronchology and Interventional Pulmonology (WABIP)",\n      "url": "https://wabip.com/"\n    },\n    {\n      "@type": "MedicalOrganization",\n      "name": "American College of Surgeons (ACS)",\n      "url": "https://www.facs.org/"\n    },\n    {\n      "@type": "MedicalOrganization",\n      "name": "International Association for the Study of Lung Cancer (IASLC)",\n      "url": "https://www.iaslc.org/"\n    },\n    {\n      "@type": "MedicalOrganization",\n      "name": "European Respiratory Society (ERS)",\n      "url": "https://www.ersnet.org/"\n    },\n    {\n      "@type": "MedicalOrganization",\n      "name": "International Society for Heart and Lung Transplantation (ISHLT)",\n      "url": "https://ishlt.org/"\n    },\n    {\n      "@type": "MedicalOrganization",\n      "name": "Sociedad de Cirujanos de Chile",\n      "url": "https://www.socich.cl/"\n    },\n    {\n      "@type": "MedicalOrganization",\n      "name": "Asociación Latinoamericana de Tórax (ALAT)",\n      "url": "https://alatorax.org/"\n    },\n    {\n      "@type": "MedicalOrganization",\n      "name": "Sociedad Chilena de Enfermedades Respiratorias (SER)",\n      "url": "https://www.serchile.cl/"\n    }\n  ],\n  "alumniOf": [\n    {\n      "@type": "CollegeOrUniversity",\n      "name": "Pontificia Universidad Católica de Chile",\n      "url": "https://www.uc.cl/"\n    },\n    {\n      "@type": "CollegeOrUniversity",\n      "name": "Universidad de Chile",\n      "url": "https://www.uchile.cl/"\n    },\n    {\n      "@type": "Hospital",\n      "name": "Hospital Universitario Puerta de Hierro Majadahonda",\n      "url": "https://www.comunidad.madrid/hospital/puertadehierro/"\n    }\n  ],\n  "address": {\n    "@type": "PostalAddress",\n    "addressLocality": "Santiago",\n    "addressRegion": "Región Metropolitana",\n    "addressCountry": "CL"\n  },\n  "identifier": [\n    {\n      "@type": "PropertyValue",\n      "propertyID": "ORCID",\n      "value": "0009-0007-0806-6679"\n    }\n  ],\n  "affiliation": [\n    {\n      "@type": "CollegeOrUniversity",\n      "name": "Universidad Finis Terrae — Facultad de Medicina",\n      "url": "https://facultadmedicina.uft.cl/"\n    }\n  ]\n}\n  </script>\n'
CSS="  <style>\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n    /* Los atributos width/height protegen del CLS; height:auto evita que\n       fijen el alto y pisen el aspect-ratio o el alto que define el CSS. */\n    img { height: auto; }\n    :root {\n      --navy:      #0c1526;\n      --navy2:     #1a2740;\n      --teal-deep: #0c4a6e;\n      --teal:      #0891b2;\n      --teal-dark: #0e7490;\n      --teal-lt:   #22d3ee;\n      --teal-pale: #ecfeff;\n      --teal-mid:  #cffafe;\n      --bg:        #ffffff;\n      --bg-alt:    #f4f8fb;\n      --text:      #1a2b3c;\n      --slate:     #3a5068;\n      --muted:     #607d93;\n      --border:    #dce8f0;\n      --serif:     'DM Serif Display', serif;\n      --sans:      'Plus Jakarta Sans', system-ui, sans-serif;\n    }\n    html { scroll-behavior: smooth; }\n    body { font-family: var(--sans); background: var(--bg); color: var(--text); -webkit-font-smoothing: antialiased; overflow-x: hidden; line-height: 1.6; }\n\n    .topbar { background: var(--navy); padding: 0.42rem 2.5rem; display: flex; justify-content: flex-end; gap: 1.25rem; flex-wrap: wrap; }\n    .topbar a { font-size: 0.7rem; letter-spacing: 0.04em; text-transform: uppercase; color: rgba(255,255,255,0.38); text-decoration: none; transition: color 0.2s; }\n    .topbar a:hover { color: rgba(255,255,255,0.8); }\n    .topbar span { color: rgba(255,255,255,0.15); }\n\n    /* ── NAV ── */\n    nav {\n      position: sticky; top: 0; z-index: 500;\n      height: 66px; background: rgba(12,21,38,0.96); backdrop-filter: blur(20px);\n      border-bottom: 1px solid rgba(255,255,255,0.07);\n      padding: 0 2.5rem;\n      display: flex; align-items: center; justify-content: space-between;\n      transition: background 0.4s, box-shadow 0.3s;\n    }\n    nav.light { background: rgba(255,255,255,0.97); border-bottom-color: var(--border); box-shadow: 0 2px 24px rgba(12,21,38,0.08); }\n    .nav-logo { text-decoration: none; display: flex; align-items: center; gap: 0.6rem; }\n    .nav-logo-mark { width: 32px; height: 32px; border-radius: 8px; background: var(--teal-deep); display: flex; align-items: center; justify-content: center; }\n    .nav-logo-mark svg { width: 16px; height: 16px; }\n    .nav-logo-text { font-size: 0.88rem; font-weight: 800; color: #fff; letter-spacing: -0.01em; transition: color 0.3s; }\n    .nav-logo-text span { color: var(--teal-lt); transition: color 0.3s; }\n    nav.light .nav-logo-text { color: var(--navy); }\n    nav.light .nav-logo-text span { color: var(--teal); }\n    .nav-links { display: flex; gap: 1.75rem; list-style: none; }\n    .nav-links a { font-size: 0.83rem; font-weight: 500; color: rgba(255,255,255,0.58); text-decoration: none; transition: color 0.2s; }\n    .nav-links a:hover { color: #fff; }\n    nav.light .nav-links a { color: var(--slate); }\n    nav.light .nav-links a:hover { color: var(--teal); }\n    .nav-cta { background: var(--teal); color: #fff; text-decoration: none; padding: 0.5rem 1.2rem; border-radius: 6px; font-size: 0.83rem; font-weight: 700; transition: background 0.2s, transform 0.15s; }\n    .nav-cta:hover { background: var(--teal-dark); transform: translateY(-1px); }\n\n    /* ── HERO ── */\n    .hero {\n      min-height: 100vh; display: flex; flex-direction: column; justify-content: flex-end;\n      position: relative; overflow: hidden;\n    }\n    .hero-bg {\n      position: absolute; inset: 0;\n      background-image: url('https://rats.cl/imgs/hero-davinci.jpg');\n      background-image: image-set(url('https://rats.cl/imgs/hero-davinci.webp') type('image/webp'), url('https://rats.cl/imgs/hero-davinci.jpg') type('image/jpeg'));\n      background-size: cover; background-position: center 25%;\n    }\n    .hero-overlay {\n      position: absolute; inset: 0;\n      background: linear-gradient(160deg, rgba(12,21,38,0.88) 0%, rgba(12,74,110,0.7) 50%, rgba(12,21,38,0.55) 100%);\n    }\n    .hero-content {\n      position: relative; z-index: 2;\n      max-width: 1100px; width: 100%; margin: 0 auto;\n      padding: 8rem 2.5rem 0;\n    }\n    .hero-badge {\n      display: inline-flex; align-items: center; gap: 0.5rem;\n      background: rgba(34,211,238,0.12); border: 1px solid rgba(34,211,238,0.3);\n      border-radius: 100px; padding: 0.35rem 1rem;\n      font-size: 0.68rem; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase;\n      color: var(--teal-lt); margin-bottom: 1.75rem;\n    }\n    .hero-badge-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--teal-lt); animation: blink 2.5s infinite; }\n    @keyframes blink { 0%,100%{opacity:1} 50%{opacity:0.3} }\n    .hero h1 {\n      font-family: var(--serif); font-size: clamp(2.8rem, 5.5vw, 4.5rem);\n      line-height: 1.1; letter-spacing: -0.025em; color: #fff;\n      margin-bottom: 1.25rem; max-width: 700px;\n    }\n    .hero h1 em { color: var(--teal-lt); font-style: italic; }\n    .hero-lead { font-size: 1.05rem; line-height: 1.75; color: rgba(255,255,255,0.68); max-width: 520px; margin-bottom: 2.25rem; }\n    .hero-btns { display: flex; gap: 0.75rem; flex-wrap: wrap; margin-bottom: 3.5rem; }\n    .btn-primary { display: inline-flex; align-items: center; gap: 0.5rem; background: var(--teal); color: #fff; text-decoration: none; padding: 0.85rem 1.75rem; border-radius: 8px; font-size: 0.9rem; font-weight: 700; transition: background 0.2s, transform 0.15s, box-shadow 0.2s; }\n    .btn-primary:hover { background: var(--teal-dark); transform: translateY(-1px); box-shadow: 0 8px 28px rgba(8,145,178,0.4); }\n    .btn-ghost { display: inline-flex; align-items: center; gap: 0.5rem; background: rgba(255,255,255,0.1); color: #fff; text-decoration: none; padding: 0.85rem 1.75rem; border-radius: 8px; font-size: 0.9rem; font-weight: 600; border: 1.5px solid rgba(255,255,255,0.28); transition: background 0.2s; }\n    .btn-ghost:hover { background: rgba(255,255,255,0.18); }\n    .statsbar {\n      position: relative; z-index: 2;\n      background: rgba(12,21,38,0.82); backdrop-filter: blur(16px);\n      border-top: 1px solid rgba(255,255,255,0.07);\n      padding: 1.5rem 2.5rem;\n      display: grid; grid-template-columns: repeat(4,1fr);\n    }\n    .stat { text-align: center; padding: 0 1rem; border-right: 1px solid rgba(255,255,255,0.07); }\n    .stat:last-child { border-right: none; }\n    .stat-n { font-family: var(--serif); font-size: 2.1rem; color: var(--teal-lt); line-height: 1; margin-bottom: 0.25rem; }\n    .stat-l { font-size: 0.7rem; color: rgba(255,255,255,0.42); line-height: 1.45; }\n\n    /* ── SECTIONS ── */\n    .section { padding: 6rem 2.5rem; }\n    .section-alt { background: var(--bg-alt); }\n    .section-dark { background: var(--navy); }\n    .inner { max-width: 1100px; margin: 0 auto; }\n    .eyebrow { font-size: 0.68rem; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: var(--teal); margin-bottom: 0.75rem; }\n    .eyebrow-w { color: var(--teal-lt); }\n    .section-title { font-family: var(--serif); font-size: clamp(1.9rem, 3vw, 2.8rem); line-height: 1.18; letter-spacing: -0.02em; color: var(--navy); margin-bottom: 1rem; }\n    .section-title.w { color: #fff; }\n    .section-lead { font-size: 1rem; line-height: 1.78; color: var(--slate); max-width: 620px; margin-bottom: 3rem; }\n    .section-lead.w { color: rgba(255,255,255,0.55); }\n\n    /* ── DA VINCI SPLIT ── */\n    .davinci-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0; min-height: 560px; }\n    .davinci-visual {\n      background: var(--navy2); display: flex; align-items: center; justify-content: center;\n      padding: 4rem; position: relative; overflow: hidden;\n    }\n    .rings { position: relative; width: 240px; height: 240px; display: flex; align-items: center; justify-content: center; flex-direction: column; gap: 1rem; }\n    .ring { position: absolute; border-radius: 50%; border: 1px solid rgba(34,211,238,0.12); }\n    .ring-1 { inset: 0; animation: spin 20s linear infinite; border-top-color: var(--teal-lt); }\n    .ring-2 { inset: 28px; animation: spin 14s linear reverse infinite; border-top-color: rgba(34,211,238,0.4); }\n    .ring-3 { inset: 56px; animation: spin 9s linear infinite; border-top-color: rgba(34,211,238,0.6); }\n    @keyframes spin { from{transform:rotate(0deg)} to{transform:rotate(360deg)} }\n    .ring-center {\n      width: 110px; height: 110px; border-radius: 50%;\n      background: radial-gradient(circle at 40% 40%, rgba(34,211,238,0.25), rgba(12,21,38,0.9));\n      border: 1px solid rgba(34,211,238,0.3);\n      display: flex; align-items: center; justify-content: center; font-size: 2.5rem;\n    }\n    .rings-label { font-size: 0.65rem; letter-spacing: 0.12em; text-transform: uppercase; color: rgba(255,255,255,0.25); margin-top: 1rem; z-index: 1; }\n    .davinci-content { background: var(--navy); padding: 5rem 4rem; display: flex; flex-direction: column; justify-content: center; }\n    .feature-list { list-style: none; display: flex; flex-direction: column; gap: 1.5rem; margin-top: 2rem; }\n    .fi { display: flex; gap: 1.1rem; align-items: flex-start; }\n    .fi-ico {\n      flex-shrink: 0; width: 40px; height: 40px; border-radius: 9px;\n      background: rgba(8,145,178,0.15); border: 1px solid rgba(8,145,178,0.25);\n      display: flex; align-items: center; justify-content: center; font-size: 1rem;\n    }\n    .fi-text h4 { font-size: 0.9rem; font-weight: 700; color: #fff; margin-bottom: 0.25rem; }\n    .fi-text p { font-size: 0.82rem; color: rgba(255,255,255,0.48); line-height: 1.6; }\n\n    /* ── BENEFITS CARDS ── */\n    .benefits-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 1.25rem; }\n    .benefit-card {\n      background: var(--bg); border: 1px solid var(--border); border-radius: 16px; padding: 2rem;\n      position: relative; overflow: hidden;\n      transition: border-color 0.25s, transform 0.25s, box-shadow 0.25s;\n    }\n    .benefit-card::before {\n      content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px;\n      background: var(--teal); transform: scaleX(0); transform-origin: left; transition: transform 0.3s;\n    }\n    .benefit-card:hover { border-color: var(--teal); transform: translateY(-4px); box-shadow: 0 16px 48px rgba(8,145,178,0.1); }\n    .benefit-card:hover::before { transform: scaleX(1); }\n    .benefit-icon { font-size: 1.75rem; margin-bottom: 1.1rem; }\n    .benefit-card h3 { font-size: 0.95rem; font-weight: 700; color: var(--navy); margin-bottom: 0.45rem; }\n    .benefit-card p { font-size: 0.83rem; line-height: 1.65; color: var(--muted); }\n    .benefit-tag { display: inline-block; margin-top: 0.85rem; font-size: 0.67rem; font-weight: 700; letter-spacing: 0.07em; text-transform: uppercase; color: var(--teal-dark); background: var(--teal-pale); border: 1px solid var(--teal-mid); padding: 0.2rem 0.6rem; border-radius: 4px; }\n\n    /* ── PROCEDURES ── */\n    .proc-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 1.25rem; }\n    .proc-card {\n      background: var(--bg); border: 1px solid var(--border); border-radius: 14px; padding: 1.75rem;\n      transition: border-color 0.2s, transform 0.2s, box-shadow 0.2s;\n    }\n    .proc-card:hover { border-color: var(--teal); transform: translateY(-2px); box-shadow: 0 8px 28px rgba(8,145,178,0.1); }\n    .proc-num { font-size: 0.65rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--teal); margin-bottom: 0.6rem; }\n    .proc-card h3 { font-size: 0.92rem; font-weight: 700; color: var(--navy); margin-bottom: 0.4rem; }\n    .proc-card p { font-size: 0.8rem; line-height: 1.6; color: var(--muted); }\n    .proc-card ul { margin: 0.5rem 0 0 1rem; font-size: 0.8rem; color: var(--muted); line-height: 1.8; }\n\n    /* ── CTA / CONTACTO ── */\n    .cta-section {\n      background: linear-gradient(135deg, var(--teal-deep) 0%, var(--teal-dark) 60%, #0369a1 100%);\n      padding: 7rem 2.5rem; text-align: center; position: relative; overflow: hidden;\n    }\n    .cta-section::before { content: ''; position: absolute; inset: 0; background: radial-gradient(ellipse 60% 80% at 50% 0%, rgba(34,211,238,0.08), transparent 70%); }\n    .cta-inner { position: relative; z-index: 1; max-width: 680px; margin: 0 auto; }\n    .cta-eyebrow { font-size: 0.68rem; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: var(--teal-lt); margin-bottom: 1rem; }\n    .cta-title { font-family: var(--serif); font-size: clamp(2rem, 3.5vw, 3rem); color: #fff; letter-spacing: -0.02em; margin-bottom: 1.25rem; }\n    .cta-sub { font-size: 1rem; color: rgba(255,255,255,0.65); line-height: 1.75; margin-bottom: 2.5rem; }\n    .cta-btns { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }\n    .btn-cta-w { display: inline-flex; align-items: center; gap: 0.5rem; background: #fff; color: var(--teal-deep); text-decoration: none; padding: 0.9rem 2rem; border-radius: 8px; font-size: 0.9rem; font-weight: 700; transition: transform 0.15s, box-shadow 0.2s; }\n    .btn-cta-w:hover { transform: translateY(-2px); box-shadow: 0 10px 28px rgba(0,0,0,0.2); }\n    .btn-cta-ghost { display: inline-flex; align-items: center; gap: 0.5rem; background: rgba(255,255,255,0.1); color: #fff; text-decoration: none; padding: 0.9rem 2rem; border-radius: 8px; font-size: 0.9rem; font-weight: 600; border: 1.5px solid rgba(255,255,255,0.25); transition: background 0.2s; }\n    .btn-cta-ghost:hover { background: rgba(255,255,255,0.18); }\n\n    /* ── FOOTER ── */\n    footer { background: var(--navy); padding: 2.5rem; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 1rem; border-top: 1px solid rgba(255,255,255,0.06); }\n    footer p { font-size: 0.78rem; color: rgba(255,255,255,0.32); }\n    .footer-links { display: flex; gap: 1.5rem; flex-wrap: wrap; }\n    .footer-links a { font-size: 0.78rem; color: rgba(255,255,255,0.32); text-decoration: none; transition: color 0.2s; }\n    .footer-links a:hover { color: var(--teal-lt); }\n\n    /* ── RESPONSIVE ── */\n    @media (max-width: 960px) {\n      .davinci-grid { grid-template-columns: 1fr; }\n      .benefits-grid, .proc-grid { grid-template-columns: 1fr 1fr; }\n      .statsbar { grid-template-columns: 1fr 1fr; }\n      .stat { border-right: none; border-bottom: 1px solid rgba(255,255,255,0.07); padding-bottom: 1rem; }\n      .stat:last-child { border-bottom: none; }\n    }\n    @media (max-width: 640px) {\n      nav, .topbar { padding: 0 1.25rem; }\n      .nav-links { display: none; }\n      .section { padding: 4rem 1.25rem; }\n      .hero-content { padding: 7rem 1.25rem 0; }\n      .statsbar { padding: 1.25rem; }\n      .benefits-grid, .proc-grid { grid-template-columns: 1fr; }\n      .davinci-content { padding: 3rem 1.5rem; }\n    }\n  \n    /* ══ CTA CONTACTO UNIFICADO ══ */\n    .cta-unified {\n      background: linear-gradient(135deg, #0c4a6e 0%, #0e7490 60%, #0369a1 100%);\n      padding: 5rem 2.5rem; text-align: center; position: relative; overflow: hidden;\n    }\n    .cta-unified::before { content:''; position:absolute; inset:0; background:radial-gradient(ellipse 60% 80% at 50% 0%, rgba(34,211,238,0.08), transparent 70%); pointer-events:none; }\n    .cta-unified > * { position: relative; z-index: 2; }\n    .cta-unified .cta-eyebrow { font-size:0.68rem; font-weight:700; letter-spacing:0.12em; text-transform:uppercase; color:#22d3ee; margin-bottom:0.75rem; }\n    .cta-unified .cta-title { font-family:'DM Serif Display',serif; font-size:clamp(1.8rem,3vw,2.6rem); color:#fff; letter-spacing:-0.02em; margin-bottom:2rem; }\n    .cta-unified .cta-contact-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:1.25rem; max-width:980px; margin:0 auto; align-items:stretch; }\n    .cta-unified .contact-card { background:rgba(255,255,255,0.07); border:1px solid rgba(255,255,255,0.12); border-radius:12px; padding:1.5rem; text-align:left; transition:background 0.2s; }\n    .cta-unified .contact-card:hover { background:rgba(255,255,255,0.11); }\n    .cta-unified .contact-card h4 { font-size:0.8rem; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:#22d3ee; margin-bottom:0.75rem; }\n    .cta-unified .ccontact-links { display:flex; flex-direction:column; gap:0.65rem; margin-top:0.5rem; }\n    .cta-unified .ccontact-link { display:flex; align-items:center; gap:0.75rem; text-decoration:none; padding:0.6rem 0.75rem; border-radius:8px; background:rgba(255,255,255,0.05); border:1px solid rgba(255,255,255,0.1); transition:background 0.2s, border-color 0.2s; }\n    .cta-unified .ccontact-link:hover { background:rgba(255,255,255,0.12); border-color:rgba(255,255,255,0.2); }\n    .cta-unified .ccontact-ico { font-size:1.1rem; flex-shrink:0; }\n    .cta-unified .ccontact-label { display:block; font-size:0.68rem; font-weight:700; letter-spacing:0.06em; text-transform:uppercase; color:rgba(255,255,255,0.4); }\n    .cta-unified .ccontact-val { display:block; font-size:0.82rem; font-weight:600; color:rgba(255,255,255,0.85); margin-top:0.1rem; }\n    @media (max-width: 768px) { .cta-unified .cta-contact-grid { grid-template-columns:1fr; } }\n\n      .authority-bio { font-size: 0.75rem; color: rgba(255,255,255,0.28); margin-top: 0.75rem; max-width: 680px; line-height: 1.5; }\n  \n    /* ── Hamburger button (desktop: hidden) ── */\n    .nav-hamburger {\n      display: none;\n      background: none; border: none; cursor: pointer;\n      padding: 0.4rem; flex-direction: column;\n      gap: 5px; align-items: center; flex-shrink: 0;\n    }\n    .nav-hamburger span {\n      display: block; width: 22px; height: 2px;\n      background: #fff; border-radius: 2px;\n      transition: transform 0.25s, opacity 0.2s;\n      pointer-events: none;\n    }\n    nav.light .nav-hamburger span { background: var(--navy, #0c1526); }\n    nav.nav-open .nav-hamburger span:nth-child(1) { transform: translateY(7px) rotate(45deg); }\n    nav.nav-open .nav-hamburger span:nth-child(2) { opacity: 0; }\n    nav.nav-open .nav-hamburger span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }\n\n    /* ═══════════════════════════════════════════════\n       MOBILE RESPONSIVE  ·  max-width 768px\n       Injected last — overrides all rules above\n    ═══════════════════════════════════════════════ */\n    @media (max-width: 768px) {\n\n      /* Global */\n      html, body { overflow-x: hidden; }\n      *, *::before, *::after { box-sizing: border-box; }\n      img, video, iframe { max-width: 100%; height: auto; display: block; }\n\n      /* Typography floor */\n      p, li, td, th, blockquote, figcaption, .hero-lead, .hero-sub,\n      .alert-strip p, .card-desc, .esp-card p, .benefit-card p { font-size: max(14px, 0.9rem) !important; line-height: 1.65 !important; }\n\n      /* ── Navigation ── */\n      nav {\n        padding-left: 1rem !important;\n        padding-right: 1rem !important;\n        position: relative;\n        flex-wrap: nowrap !important;\n        display: flex !important;\n        align-items: center !important;\n      }\n      .nav-hamburger { display: flex !important; margin-left: auto; }\n      .nav-cta { display: none !important; }\n\n      /* Nav links: hidden by default, drop down when .nav-open */\n      .nav-links {\n        display: none !important;\n        flex-direction: column !important;\n        position: absolute !important;\n        top: 100% !important; left: 0 !important; right: 0 !important;\n        background: var(--navy, #0c1526) !important;\n        padding: 0.75rem 1.25rem 1.25rem !important;\n        gap: 0 !important;\n        z-index: 9999 !important;\n        box-shadow: 0 12px 40px rgba(0,0,0,0.45) !important;\n        border-top: 1px solid rgba(255,255,255,0.07) !important;\n        list-style: none !important;\n      }\n      nav.nav-open .nav-links { display: flex !important; }\n      .nav-links li { width: 100%; }\n      .nav-links a {\n        display: block !important;\n        padding: 0.7rem 0 !important;\n        border-bottom: 1px solid rgba(255,255,255,0.06) !important;\n        color: rgba(255,255,255,0.85) !important;\n        font-size: 0.9rem !important;\n        font-weight: 500 !important;\n        text-decoration: none !important;\n        width: 100% !important;\n      }\n      .nav-links li:last-child a { border-bottom: none !important; }\n\n      /* ── Topbar & breadcrumb ── */\n      .topbar, .breadcrumb {\n        padding-left: 1rem !important;\n        padding-right: 1rem !important;\n        font-size: 0.72rem !important;\n        white-space: normal !important;\n      }\n\n      /* ── Sections & inner containers ── */\n      .section, section {\n        padding-left: 1rem !important;\n        padding-right: 1rem !important;\n      }\n      .inner, .page-hero, .content, .sec,\n      .article-hero, .article-hero-inner,\n      .cta-bottom, .cta-section, .main-wrap { padding-left: 1rem !important; padding-right: 1rem !important; }\n\n      /* ── Footer ── */\n      footer {\n        padding-left: 1rem !important; padding-right: 1rem !important;\n        flex-direction: column !important;\n        gap: 1.25rem !important;\n        text-align: center !important;\n      }\n      .footer-links { flex-wrap: wrap !important; justify-content: center !important; gap: 0.75rem !important; }\n      .footer-inner, .footer-brand { flex-direction: column !important; gap: 1rem !important; text-align: center !important; }\n\n      /* ── Hero sections ── */\n      .hero { min-height: 90vh !important; }\n      .hero-content { padding: 6rem 1rem 2rem !important; }\n      .hero-inner { padding: 6rem 1rem 3rem !important; }\n      .hero-h1, .hero h1 { font-size: clamp(2rem, 8vw, 3rem) !important; }\n      h1 { font-size: clamp(1.9rem, 7.5vw, 3rem) !important; }\n      h2 { font-size: clamp(1.5rem, 5.5vw, 2.2rem) !important; }\n      .hero-btns, .hero-ctas, .hero-actions, .hero-cta-group {\n        flex-direction: column !important;\n        gap: 0.75rem !important;\n        width: 100% !important;\n      }\n\n      /* ── Buttons ── */\n      .btn-primary, .btn-ghost, .btn-outline,\n      .btn-hero-primary, .btn-hero-secondary {\n        width: 100% !important;\n        text-align: center !important;\n        justify-content: center !important;\n        box-sizing: border-box !important;\n      }\n\n      /* ── ALL GRIDS → single column ── */\n      .esp-grid, .cards-grid, .about-grid, .audience-grid,\n      .bio-wrap, .benefits-grid, .proc-grid, .davinci-grid,\n      .ebus-grid, .ebus-cards, .ablacion-cards,\n      .two-col, .medicos-grid, .interv-grid,\n      .approach-grid, .pathology-grid,\n      .rigida-grid, .crio-grid, .crio-uses-grid, .tech-grid,\n      .types-grid, .tnm-intro, .cryo-mechanic, .alcance-list,\n      .study-grid, .equipo-grid, .img-list-block,\n      .stent-vs-grid, .indic-two-col, .complic-grid,\n      .stent-evidence, .eco-grid, .abl-card-body, .abl-row,\n      .contact-grid, .page-body, .services-row, .indic-grid,\n      .proc-table-grid, .hero-inner-grid {\n        grid-template-columns: 1fr !important;\n      }\n      .path-two-col { column-count: 1 !important; columns: 1 !important; }\n      .img-list-block.reverse { direction: ltr !important; }\n      .sidebar { display: none !important; }\n      .abl-desc-col { border-right: none !important; border-bottom: 1px solid var(--border, #e5e7eb) !important; }\n      .proc-col:first-child { border-right: none !important; border-bottom: 1px solid var(--border, #e5e7eb) !important; }\n\n      /* ── Bio credentials: 2 columns on mobile ── */\n      .bio-creds { grid-template-columns: 1fr 1fr !important; }\n      .bio-section-light .bio-wrap { grid-template-columns: 1fr !important; }\n\n      /* ── Statsbar ── */\n      .statsbar {\n        grid-template-columns: 1fr 1fr !important;\n        padding: 1.25rem 1rem !important;\n      }\n      .stats-strip { grid-template-columns: 1fr 1fr !important; }\n      .stat {\n        border-right: none !important;\n        border-bottom: 1px solid rgba(255,255,255,0.07) !important;\n        padding-bottom: 1rem !important;\n      }\n      .stat:last-child { border-bottom: none !important; padding-bottom: 0 !important; }\n      .hero-statsbar {\n        flex-direction: column !important;\n        padding: 1.25rem 1rem !important;\n        gap: 1rem !important;\n      }\n      .hero-stat {\n        border-right: none !important;\n        border-bottom: 1px solid rgba(255,255,255,0.1) !important;\n        padding-bottom: 0.75rem !important;\n      }\n      .hero-stat:last-child { border-bottom: none !important; }\n\n      /* ── CTA contact grid (Hable con el especialista) ── */\n      .cta-contact-grid, .cta-unified .cta-contact-grid,\n      .ccontact-links {\n        grid-template-columns: 1fr !important;\n        flex-direction: column !important;\n      }\n      .contact-card { display: block !important; }\n\n      /* ── Tables ── */\n      table { display: block; overflow-x: auto; -webkit-overflow-scrolling: touch; width: 100%; }\n      .grouping-table { font-size: 0.78rem !important; }\n      .grouping-table td, .grouping-table th { padding: 0.4rem 0.5rem !important; }\n\n      /* ── Misc layout fixes ── */\n      .alert-strip { flex-direction: column !important; gap: 0.75rem !important; }\n      .doctor-wrap, .bio-wrap-row { flex-direction: column !important; align-items: flex-start !important; gap: 1.5rem !important; }\n      .survival-row { flex-wrap: wrap !important; }\n      .aquire-strip, .abl-card-header { flex-direction: column !important; gap: 1rem !important; }\n      .as-sep { display: none !important; }\n      .page-nav { flex-direction: column !important; padding: 2rem 1rem !important; gap: 1rem !important; }\n      .page-nav-link.next { text-align: left !important; }\n      .evidence-strip { grid-template-columns: 1fr 1fr !important; }\n      .abl-card-kpis { gap: 1rem !important; flex-wrap: wrap !important; }\n      .hero-stats { flex-direction: row !important; flex-wrap: wrap !important; gap: 0.75rem !important; }\n\n      /* ── Bio author grid mobile fix ── */\n      .bio-author-grid {\n        grid-template-columns: 1fr !important;\n        gap: 1.5rem !important;\n      }\n      .bio-author-grid > div {\n        width: 100% !important;\n        max-width: 100% !important;\n        overflow: hidden !important;\n        padding-right: 0 !important;\n      }\n\n      /* ── Bio wrap (Sobre el autor) mobile fix ── */\n      .bio-wrap {\n        grid-template-columns: 1fr !important;\n        gap: 1.5rem !important;\n        width: 100% !important;\n        overflow: hidden !important;\n      }\n      .bio-wrap > div {\n        width: 100% !important;\n        max-width: 100% !important;\n        overflow: hidden !important;\n        padding-right: 0 !important;\n      }\n      .bio-name { font-size: 1.8rem !important; }\n    }\n\n  \n    /* ── FAQ (visible, marcado con JSON-LD) ── */\n    .faq-list { max-width: 760px; }\n    .faq-item { border-bottom: 1px solid var(--border); }\n    .faq-q { width: 100%; background: none; border: none; cursor: pointer; display: flex;\n      align-items: center; justify-content: space-between; gap: 1rem; padding: 1.2rem 0;\n      text-align: left; font-family: var(--sans); font-size: 0.95rem; font-weight: 600;\n      color: var(--navy); transition: color 0.2s; }\n    .faq-q:hover { color: var(--teal); }\n    .faq-arrow { flex-shrink: 0; width: 22px; height: 22px; border-radius: 50%;\n      border: 1.5px solid var(--border); color: var(--muted); display: flex; align-items: center;\n      justify-content: center; font-size: 0.9rem; transition: all 0.3s; }\n    .faq-item.open .faq-arrow { background: var(--teal); border-color: var(--teal); color: #fff; transform: rotate(45deg); }\n    .faq-a { max-height: 0; overflow: hidden; font-size: 0.88rem; line-height: 1.78; color: var(--slate);\n      transition: max-height 0.35s ease, padding 0.35s; }\n    .faq-item.open .faq-a { max-height: 420px; padding-bottom: 1.25rem; }\n    .faq-h2 { font-family: var(--serif); font-size: clamp(1.6rem, 3vw, 2.2rem); color: var(--navy);\n      margin: 0 0 1.8rem; line-height: 1.2; }\n\n  \n    /* ── Box de perfil dentro del bloque biográfico ── */\n    .perfil-box {\n      display: flex; align-items: center; gap: 0.85rem;\n      margin-top: 1.5rem; padding: 0.9rem 1.1rem; max-width: 430px;\n      background: var(--teal-pale); color: var(--teal-dark);\n      border: 1px solid var(--teal); border-left: 4px solid var(--teal);\n      border-radius: 10px; text-decoration: none;\n      transition: background 0.2s, box-shadow 0.2s, transform 0.15s;\n    }\n    .perfil-box:hover {\n      background: #fff;\n      box-shadow: 0 8px 24px rgba(8,145,178,0.18);\n      transform: translateY(-2px);\n    }\n    .perfil-box-txt { flex: 1; }\n    .perfil-box-t {\n      display: block; font-size: 0.84rem; font-weight: 700;\n      color: var(--navy); letter-spacing: -0.01em;\n    }\n    .perfil-box-s {\n      display: block; font-size: 0.74rem; line-height: 1.45;\n      color: var(--muted); margin-top: 0.15rem;\n    }\n    @media (max-width: 768px) { .perfil-box { max-width: 100%; } }\n</style>\n  <style>\n    /* ── Subpágina: opérculo torácico ── */\n    .hero.hero-sub { min-height: 72vh; }\n    .crumbs { font-size: 0.78rem; color: rgba(255,255,255,0.55); margin-bottom: 1.25rem; display: flex; gap: 0.5rem; align-items: center; flex-wrap: wrap; }\n    .crumbs a { color: rgba(255,255,255,0.75); text-decoration: none; }\n    .crumbs a:hover { color: #fff; }\n    .tos-spaces { margin-top: 2.5rem; }\n    .tos-why { margin-top: 2rem; grid-template-columns: 1fr 1fr; }\n    .tos-one { grid-column: 1 / -1; }\n    .tos-why .benefit-card h3 { margin-bottom: 0.5rem; }\n    .dx-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 1.25rem; margin-top: 2.5rem; }\n    .dx-item { background: var(--bg-alt); border: 1px solid var(--border); border-radius: 14px; padding: 1.5rem; }\n    .dx-item h3 { font-size: 0.98rem; font-weight: 700; color: var(--navy); margin-bottom: 0.5rem; letter-spacing: -0.01em; }\n    .dx-item p { font-size: 0.86rem; color: var(--slate); line-height: 1.7; }\n    .dx-note { margin-top: 1.5rem; background: var(--teal-pale); border: 1px solid var(--teal-mid); border-radius: 14px; padding: 1.75rem 2rem; }\n    .dx-note h3 { font-size: 1.05rem; font-weight: 700; color: var(--teal-deep); margin-bottom: 0.6rem; }\n    .dx-note p { font-size: 0.92rem; color: var(--slate); line-height: 1.75; }\n    .fi-num { display: inline-flex; width: 100%; height: 100%; align-items: center; justify-content: center; font-weight: 800; font-size: 0.95rem; color: var(--teal-lt); }\n    .cmp-wrap { overflow-x: auto; margin-top: 2.5rem; border: 1px solid var(--border); border-radius: 14px; background: var(--bg); }\n    .cmp-table { width: 100%; border-collapse: collapse; font-size: 0.86rem; min-width: 760px; }\n    .cmp-table th, .cmp-table td { padding: 0.95rem 1.1rem; text-align: left; vertical-align: top; border-bottom: 1px solid var(--border); line-height: 1.55; }\n    .cmp-table th { background: var(--navy); color: #fff; font-size: 0.72rem; letter-spacing: 0.06em; text-transform: uppercase; font-weight: 700; }\n    .cmp-table tbody tr:last-child td { border-bottom: none; }\n    .cmp-table td { color: var(--slate); }\n    .cmp-table td strong { color: var(--navy); }\n    .cmp-table tr.cmp-hl td { background: var(--teal-pale); }\n    .vasc-box { display: grid; grid-template-columns: 1.1fr 1fr; gap: 3rem; align-items: start; background: var(--bg-alt); border: 1px solid var(--border); border-radius: 18px; padding: 2.5rem; }\n    .vasc-list { list-style: none; display: flex; flex-direction: column; gap: 1rem; }\n    .vasc-list li { background: var(--bg); border: 1px solid var(--border); border-left: 4px solid var(--teal); border-radius: 10px; padding: 1rem 1.25rem; font-size: 0.9rem; color: var(--slate); line-height: 1.65; }\n    .vasc-list li strong { color: var(--navy); display: block; margin-bottom: 0.2rem; }\n    .ref-label { font-size: 0.8rem; font-weight: 600; color: var(--teal-lt); margin-bottom: 0.75rem; }\n    .ref-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 1.25rem; margin-top: 2.5rem; }\n    .ref-card { background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.1); border-radius: 14px; padding: 1.6rem; }\n    .ref-card h3 { color: #fff; font-size: 1rem; font-weight: 700; margin-bottom: 0.9rem; }\n    .ref-card ul { list-style: none; display: flex; flex-direction: column; gap: 0.6rem; }\n    .ref-card li { font-size: 0.85rem; color: rgba(255,255,255,0.72); line-height: 1.6; padding-left: 1rem; position: relative; }\n    .ref-card li::before { content: ''; position: absolute; left: 0; top: 0.62em; width: 5px; height: 5px; border-radius: 50%; background: var(--teal-lt); }\n    .ref-card a { color: var(--teal-lt); font-weight: 600; }\n    #derivadores .section-title.w, #derivadores .section-lead.w { max-width: 800px; }\n    @media (max-width: 960px) {\n      .dx-grid, .ref-grid { grid-template-columns: 1fr 1fr; }\n      .vasc-box { grid-template-columns: 1fr; gap: 1.5rem; padding: 1.75rem; }\n    }\n    @media (max-width: 640px) {\n      .dx-grid, .ref-grid, .tos-why { grid-template-columns: 1fr; }\n      .hero.hero-sub { min-height: 80vh !important; }\n    }\n  </style>\n"
