SCRIPTS="  <script>\n    const nav = document.getElementById('main-nav');\n    window.addEventListener('scroll', () => {\n      nav.classList.toggle('light', window.scrollY > 80);\n    }, { passive: true });\n  </script>\n\n\n  <script>\n    document.querySelectorAll('.faq-q').forEach(function (b) {\n      b.addEventListener('click', function () { b.parentElement.classList.toggle('open'); });\n    });\n  </script>\n\n  <script>\n    /* El vídeo del robot (2,6 MB) no se descarga al cargar la página:\n       se carga y arranca solo cuando el usuario llega a esa sección. */\n    (function () {\n      var v = document.querySelector('video[data-src]');\n      if (!v) return;\n      function cargar() {\n        if (v.dataset.cargado) return;\n        v.dataset.cargado = '1';\n        var s = document.createElement('source');\n        s.src = v.dataset.src; s.type = 'video/mp4';\n        v.appendChild(s); v.load();\n        var p = v.play(); if (p && p.catch) p.catch(function () {});\n      }\n      if (!('IntersectionObserver' in window)) { cargar(); return; }\n      var io = new IntersectionObserver(function (es) {\n        es.forEach(function (e) { if (e.isIntersecting) { cargar(); io.disconnect(); } });\n      }, { rootMargin: '300px' });\n      io.observe(v);\n    })();\n  </script>\n"
